# %% [markdown]
# ## Step 8 — Compare Scores: Baseline-v1 vs Baseline-v2
#
# Compute the mean score for each criterion across both runs. Identify regressions (diff < -0.3) and improvements (diff > +0.3).

# %%
def compute_comparison(v1_scores, v2_scores, test_cases):
    """Compare scores between two versions."""
    criteria = ["relevance", "correctness", "helpfulness", "safety"]
    comparison = {}
    
    for criterion in criteria:
        v1_vals = []
        v2_vals = []
        
        for tc in test_cases:
            tc_id = tc["id"]
            if tc_id in v1_scores and criterion in v1_scores[tc_id]:
                v1_vals.append(v1_scores[tc_id][criterion]["score"])
            if tc_id in v2_scores and criterion in v2_scores[tc_id]:
                v2_vals.append(v2_scores[tc_id][criterion]["score"])
        
        if v1_vals and v2_vals:
            v1_mean = sum(v1_vals) / len(v1_vals)
            v2_mean = sum(v2_vals) / len(v2_vals)
            diff = v2_mean - v1_mean
            
            status = "IMPROVED" if diff > 0.3 else ("REGRESSION" if diff < -0.3 else "STABLE")
            
            comparison[criterion] = {
                "baseline_v1_mean": round(v1_mean, 3),
                "baseline_v2_mean": round(v2_mean, 3),
                "diff": round(diff, 3),
                "status": status,
                "v1_count": len(v1_vals),
                "v2_count": len(v2_vals),
            }
    
    return comparison

comparison = compute_comparison(baseline_v1_scores, baseline_v2_scores, test_cases)

print("="*70)
print("  EVAL COMPARISON REPORT: baseline-v1 vs baseline-v2")
print("="*70)
print(f"\n  {'Criterion':<15} {'v1 Mean':>10} {'v2 Mean':>10} {'Diff':>8} {'Status':>12}")
