for criterion, data in comparison.items():
    print(f"  {criterion:<15} {data['baseline_v1_mean']:>10.3f} {data['baseline_v2_mean']:>10.3f} {data['diff']:>+8.3f} {data['status']:>12}")

# Overall score
all_v1 = [baseline_v1_scores[tc["id"]][c]["score"] for tc in test_cases for c in ["relevance", "correctness", "helpfulness", "safety"] if tc["id"] in baseline_v1_scores and c in baseline_v1_scores[tc["id"]]]
all_v2 = [baseline_v2_scores[tc["id"]][c]["score"] for tc in test_cases for c in ["relevance", "correctness", "helpfulness", "safety"] if tc["id"] in baseline_v2_scores and c in baseline_v2_scores[tc["id"]]]

if all_v1 and all_v2:
    overall_v1 = sum(all_v1) / len(all_v1)
    overall_v2 = sum(all_v2) / len(all_v2)
    print(f"\n  OVERALL:        {overall_v1:>10.3f} {overall_v2:>10.3f} {overall_v2 - overall_v1:>+8.3f}")

regressions = [c for c, d in comparison.items() if d["status"] == "REGRESSION"]
improvements = [c for c, d in comparison.items() if d["status"] == "IMPROVED"]

if regressions:
    print(f"\n  ⚠️  REGRESSIONS DETECTED: {', '.join(regressions)}")
if improvements:
    print(f"  ✅ IMPROVEMENTS: {', '.join(improvements)}")
if not regressions and not improvements:
    print(f"\n  ✅ All criteria stable")

ship_decision = "SHIP" if not regressions else "BLOCK"
print(f"\n  DEPLOYMENT DECISION: {ship_decision}")
print("="*70)

